"""NLCD Level II code to curve number, by hydrologic condition and soil group.

Source
------
NRCS (1986), TR-55, Urban Hydrology for Small Watersheds, 2nd ed., June 1986,
210-VI-TR-55:
    Table 2-2a  urban and residential land uses
    Table 2-2b  cultivated agricultural land
    Table 2-2c  other agricultural land
    Table 2-2d  arid and semiarid rangeland

The same values are carried today by NRCS in National Engineering Handbook
Part 630, Chapter 9, "Hydrologic Soil-Cover Complexes" (July 2004),
210-VI-NEH, as Tables 9-1, 9-2, 9-3 and 9-5. Chapter 9 is the live NRCS
document; TR-55 is the one everyone cites.

Every tabulated value in both sources carries the footnote "average runoff
condition, and Ia = 0.2S". The table and the lambda are ONE OBJECT. A curve
number lifted from this table and dropped into a lambda = 0.05 runoff equation
is not a lambda = 0.05 curve number; convert it first with
cnkit.core.cn05_from_cn20.

The per-class `_source` strings record which row was used and, where there is
no TR-55 row at all, say so explicitly rather than implying a lookup.

For a worked, machine-checked example of reading this table, see cn_lookup and
cn_table_frame below. Variable docstrings are not executed by doctest, so no
example is placed here.
"""

# Hydrologic soil group to column index in the CN_TABLE tuples.
#
# NEH-630 Chapter 7, "Hydrologic Soil Groups" (January 2009), defines the four
# groups by the SATURATED HYDRAULIC CONDUCTIVITY of the least transmissive
# layer, jointly with depth to a water impermeable layer and depth to the
# seasonal high water table, with depth-dependent thresholds. It is not a
# minimum infiltration rate criterion, whatever older texts say.
#
# Chapter 7 also states that soil series hydrologic soil group lists are
# obsolete and their use should be discontinued.
_HSG_INDEX = {"A": 0, "B": 1, "C": 2, "D": 3,
              # Dual groups: the first letter applies if the soil is
              # adequately drained, the second (always D) if it is not.
              # Undrained is the conservative assumption for design.
              "A/D": 3, "B/D": 3, "C/D": 3, "D/D": 3}


def _validate_condition(condition):
    if not isinstance(condition, str):
        raise TypeError(
            "condition must be 'poor', 'fair', or 'good'"
        )
    condition = condition.lower()
    if condition not in ("poor", "fair", "good"):
        raise ValueError("condition must be 'poor', 'fair', or 'good'")
    return condition


def cn_lookup(nlcd, hsg, condition="fair", drained=False):
    """Curve number for a land cover class and hydrologic soil group.

    Parameters
    ----------
    nlcd : int or array-like of int
        NLCD Level II code.
    hsg : str or array-like of str
        'A', 'B', 'C', 'D', or a dual group 'A/D', 'B/D', 'C/D', 'D/D'.
    condition : {'poor', 'fair', 'good'}
        Hydrologic condition. This is the assumption that cannot be observed
        from space. Run the workshop exercise with all three and look at the
        spread before trusting any single answer.
    drained : bool
        For dual hydrologic soil groups only. False (the default) treats a
        dual group as D, which is the conservative design assumption. True
        uses the first letter, which requires that adequate artificial
        drainage actually exists and has been verified.

    Returns
    -------
    float or numpy.ndarray of float. NaN where the class is unrecognised.

    Source
    ------
    Values from TR-55 (June 1986), Tables 2-2a, 2-2b, 2-2c and 2-2d; carried
    today by NRCS as NEH-630 Chapter 9, "Hydrologic Soil-Cover Complexes"
    (July 2004), Tables 9-1, 9-2, 9-3 and 9-5. Every value in both sources
    carries the footnote "average runoff condition, and Ia = 0.2S", so what
    this function returns is a lambda = 0.20 curve number and nothing else.

    Hydrologic soil groups follow NEH-630 Chapter 7 (January 2009), which
    defines them by saturated hydraulic conductivity of the least transmissive
    layer together with depth to a water impermeable layer and depth to the
    seasonal high water table, on depth-dependent thresholds.

    Examples
    --------
    Row crops on a B/D dual soil group. The default is the UNDRAINED letter,
    which is always D, because that is the conservative design assumption.

    >>> from cnkit import cn_lookup
    >>> cn_lookup(82, "B/D")
    90.0

    Claiming drainage moves the answer ten curve numbers. Only pass
    drained=True where adequate artificial drainage has actually been
    verified in the field, not merely assumed from a soil name.

    >>> cn_lookup(82, "B/D", drained=True)
    80.0
    >>> float(cn_lookup(99, "B"))            # unrecognised NLCD class
    nan
    """
    condition = _validate_condition(condition)

    scalar = np.isscalar(nlcd) and isinstance(hsg, str)
    nlcd_arr = np.atleast_1d(np.asarray(nlcd)).astype(int)
    hsg_arr = np.atleast_1d(np.asarray(hsg)).astype(str)

    if nlcd_arr.shape != hsg_arr.shape:
        nlcd_arr, hsg_arr = np.broadcast_arrays(nlcd_arr, hsg_arr)

    out = np.full(nlcd_arr.shape, np.nan, dtype=float)
    for i, (lc, sg) in enumerate(zip(nlcd_arr.ravel(), hsg_arr.ravel())):
        entry = CN_TABLE.get(int(lc))
        if entry is None:
            continue
        sg = sg.strip().upper()
        if drained and "/" in sg:
            idx = _HSG_INDEX.get(sg.split("/")[0])
        else:
            idx = _HSG_INDEX.get(sg)
        if idx is None:
            continue
        out.ravel()[i] = float(entry[condition][idx])

    return float(out.ravel()[0]) if scalar else out


def cn_table_frame(condition="fair"):
    """The whole lookup as a tidy DataFrame. Useful for a slide or a handout.

    Source
    ------
    A reshaping of CN_TABLE, whose values come from TR-55 (June 1986) Tables
    2-2a to 2-2d, carried today as NEH-630 Chapter 9 (July 2004) Tables 9-1,
    9-2, 9-3 and 9-5. The `source` column reproduces the per-class provenance
    string, including the classes that have no TR-55 basis at all.

    Examples
    --------
    >>> from cnkit import cn_table_frame
    >>> df = cn_table_frame("fair")
    >>> df.loc[41, "class"]
    'Deciduous Forest'
    >>> rows = df.loc[[41, 82], ["CN_A", "CN_B", "CN_C", "CN_D"]].to_dict("index")
    >>> rows[41] == {"CN_A": 36, "CN_B": 60, "CN_C": 73, "CN_D": 79}
    True
    >>> rows[82] == {"CN_A": 70, "CN_B": 80, "CN_C": 87, "CN_D": 90}
    True
    >>> df.loc[90, "source"].startswith("ASSUMPTION")
    True
    """
    condition = _validate_condition(condition)
    rows = []
    for code, name in NLCD_CLASSES.items():
        vals = CN_TABLE[code][condition]
        rows.append({
            "nlcd": code, "class": name,
            "CN_A": vals[0], "CN_B": vals[1],
            "CN_C": vals[2], "CN_D": vals[3],
            "source": CN_TABLE[code]["_source"],
        })
    return pd.DataFrame(rows).set_index("nlcd")


def condition_spread(nlcd, hsg, drained=False):
    """CN under poor, fair, and good, plus the spread.

    This is the Module 4 exercise in one call. The spread is the magnitude of
    an assumption nobody can verify from imagery. Compare it against whatever
    land cover change signal you just measured, and be honest about which is
    larger.

    Source
    ------
    The three conditions are the poor, fair and good hydrologic condition rows
    of TR-55 (June 1986) Tables 2-2a to 2-2d, carried today as NEH-630
    Chapter 9 (July 2004) Tables 9-1, 9-2, 9-3 and 9-5. The spread is not from
    any source; it is the difference between two rows of the same table.

    Examples
    --------
    Pasture on a C soil. Twelve curve numbers separate poor from good, and no
    optical sensor can tell you which row applies, because grazing intensity
    is not a spectral property.

    >>> from cnkit import condition_spread
    >>> vals = condition_spread(81, "C")
    >>> [vals["poor"], vals["fair"], vals["good"]]
    [86.0, 79.0, 74.0]
    >>> float(vals["spread"])
    12.0

    Twelve CN units is larger than most multi-decade land cover change
    signals. Report the spread beside the change, or the change is not a
    result.
    """
    vals = {c: cn_lookup(nlcd, hsg, condition=c, drained=drained)
            for c in ("poor", "fair", "good")}
    vals["spread"] = np.asarray(vals["poor"]) - np.asarray(vals["good"])
    return vals


def composite_from_areas(df, condition="fair", drained=False,
                         nlcd_col="nlcd", hsg_col="hsg", area_col="area"):
    """Composite CN from a table of (land cover, soil group, area) rows.

    Returns a dict with both weighting conventions, because they differ and
    the difference matters. See cnkit.core.composite_runoff for what that
    difference does to a design storm.

    Source
    ------
    Curve numbers from TR-55 (June 1986) Tables 2-2a to 2-2d, carried today as
    NEH-630 Chapter 9 (July 2004) Tables 9-1, 9-2, 9-3 and 9-5. The CN
    weighting follows TR-55 Worksheet 2, which is a worksheet procedure and
    not a numbered equation. TR-55 page 2-11 warns that a weighted CN loses
    accuracy below 0.5 inches of runoff and directs you to another procedure
    below a weighted CN of 40. The S weighting has no published source; see
    cnkit.core.composite_cn_via_S.

    Examples
    --------
    >>> import pandas as pd
    >>> from cnkit import composite_from_areas
    >>> df = pd.DataFrame({"nlcd": [24, 41], "hsg": ["C", "B"],
    ...                    "area": [0.6, 0.4]})
    >>> out = composite_from_areas(df)
    >>> round(out["cn_weighted_CN"], 2), round(out["cn_weighted_S"], 2)
    (80.4, 76.63)
    >>> out["n_polygons"], round(out["percent_area_unmapped"], 1)
    (2, 0.0)
    """

    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")
    required = {nlcd_col, hsg_col, area_col}
    missing = sorted(required.difference(df.columns))
    if missing:
        raise ValueError("df is missing required columns: " + ", ".join(missing))
    condition = _validate_condition(condition)

    cns = cn_lookup(df[nlcd_col].values, df[hsg_col].values,
                    condition=condition, drained=drained)
    areas = df[area_col].values.astype(float)

    if areas.size == 0:
        raise ValueError("df must contain at least one row")
    if not np.isfinite(areas).all() or np.any(areas < 0.0):
        raise ValueError("area values must be finite and non-negative")
    if float(areas.sum()) <= 0.0:
        raise ValueError("area values must have a positive total")

    ok = np.isfinite(cns)
    if not ok.any():
        raise ValueError("no recognisable land cover and soil group pairs")

    unmapped = float(areas[~ok].sum() / areas.sum() * 100.0)

    return {
        "cn_weighted_CN": composite_cn(cns[ok], areas[ok]),
        "cn_weighted_S": composite_cn_via_S(cns[ok], areas[ok]),
        "condition": condition,
        "percent_area_unmapped": unmapped,
        "n_polygons": int(ok.sum()),
    }


# =========================================================================
# cnkit.events
# =========================================================================

"""Storm event separation and baseflow separation.

Nobody writes event separation live in a workshop. This module exists so the
Module 7 exercise is about interpreting the CN-versus-P plot, not about
debugging a rolling window at 3:15 in the afternoon.

Two things happen here:

1. RAINFALL EVENTS are cut out of an hourly precipitation series using a
   minimum inter-event dry period and a minimum depth threshold.
2. DIRECT RUNOFF is separated from baseflow in the daily discharge series,
   because the curve number equation predicts event runoff volume, not total
   streamflow. Failing to remove baseflow inflates every back-calculated CN,
   and it inflates small events most, which is precisely the regime where
   the lambda argument lives.

The default 1 inch (25.4 mm) minimum event depth follows Brandao, Schwamback,
Ballarin, Ramirez-Avila, Vasconcelos and Oliveira (2025), J. Hydrology 655,
132941, doi:10.1016/j.jhydrol.2025.132941, who found across 3,578 watersheds
that a 25.4 mm event-selection threshold improved CN calibration.

EWRI Curve Number Hydrology and Remote Sensing Task Committees, 2026.
"""


# 1 cfs-day over 1 square mile, expressed as a depth in inches.
#   (1 ft3/s)(86400 s) / (5280 ft)^2 * (12 in/ft) = 0.0371901 in
# Defined here rather than imported from cnkit.data, because data.py
# needs `requests` and this module must not. cnkit.data re-exports the
# same constant and a test pins the two together.
CFS_DAY_PER_SQMI_TO_INCHES = 0.0371901

_EVENT_COLUMNS = [
    "start",
    "end",
    "duration_hr",
    "P_in",
    "peak_intensity_in_hr",
]
_BASEFLOW_METHODS = {"local_minimum", "lyne_hollick"}


def separate_rainfall_events(precip, min_dry_hours=6, min_depth_in=1.0):
    """Cut an hourly precipitation series into discrete storm events.

    Parameters
    ----------
    precip : pandas.Series
        Hourly precipitation depth in inches, indexed by a DatetimeIndex.
    min_dry_hours : int
        Consecutive dry hours required to end one event and start the next.
        Six hours is a common choice for basins of this size. Larger values
        merge storms; smaller values split single storms into fragments and
        systematically bias CN upward.
    min_depth_in : float
        Events smaller than this are discarded.

    Returns
    -------
    pandas.DataFrame
        Columns: start, end, duration_hr, P_in, peak_intensity_in_hr

    Source
    ------
    The inter-event dry period is a convention, not a published equation. The
    1 inch (25.4 mm) default minimum event depth follows Brandao, Schwamback,
    Ballarin, Ramirez-Avila, Vasconcelos and Oliveira (2025), Journal of
    Hydrology 655, 132941, doi:10.1016/j.jhydrol.2025.132941, who found across
    3,578 watersheds that a 25.4 mm event-selection threshold improved curve
    number calibration.

    Examples
    --------
    Two storms in one 48 hour synthetic record, separated by a 24 hour dry
    gap. Four hours at 0.4 in/hr, then three hours at 0.5 in/hr.

    >>> import numpy as np, pandas as pd
    >>> from cnkit import separate_rainfall_events
    >>> hours = pd.Timestamp("2020-06-01") + pd.to_timedelta(np.arange(48),
    ...                                                      unit="h")
    >>> p = pd.Series(0.0, index=hours)
    >>> p.iloc[2:6] = 0.4
    >>> p.iloc[30:33] = 0.5
    >>> ev = separate_rainfall_events(p)
    >>> [round(x, 2) for x in ev["P_in"]], ev["duration_hr"].tolist()
    ([1.6, 1.5], [4.0, 3.0])

    Both survive the 1 inch threshold. Raising it to 1.55 inches keeps only
    the first, which is exactly the selection decision that shifts a fitted
    curve number.

    >>> len(separate_rainfall_events(p, min_depth_in=1.55))
    1
    """
    if not isinstance(precip, pd.Series):
        raise TypeError("precip must be a pandas Series")
    if not isinstance(precip.index, pd.DatetimeIndex):
        raise TypeError("precip must be indexed by a DatetimeIndex")
    if precip.index.has_duplicates:
        raise ValueError("precip index must not contain duplicate timestamps")
    if isinstance(min_dry_hours, bool) or not isinstance(min_dry_hours, (int, np.integer)):
        raise TypeError("min_dry_hours must be a positive integer")
    if min_dry_hours < 1:
        raise ValueError("min_dry_hours must be at least 1")
    if not np.isfinite(min_depth_in) or min_depth_in < 0.0:
        raise ValueError("min_depth_in must be a finite, non-negative depth")

    p = precip.sort_index().fillna(0.0).astype(float)
    if (p < 0.0).any():
        raise ValueError("precip must not contain negative depths")
    wet = p > 0.0

    # Label each contiguous wet run, allowing gaps shorter than min_dry_hours.
    dry_run = (~wet).astype(int).groupby(wet.cumsum()).cumsum()
    break_here = (~wet) & (dry_run >= min_dry_hours)
    event_id = break_here.cumsum().where(wet)

    rows = []
    for eid, grp in p.groupby(event_id):
        if pd.isna(eid):
            continue
        grp = grp[grp.index >= grp[grp > 0].index.min()]
        grp = grp[grp.index <= grp[grp > 0].index.max()]
        depth = float(grp.sum())
        if depth < min_depth_in:
            continue
        rows.append({
            "start": grp.index.min(),
            "end": grp.index.max(),
            "duration_hr": float(
                (grp.index.max() - grp.index.min()).total_seconds() / 3600.0
            ) + 1.0,
            "P_in": depth,
            "peak_intensity_in_hr": float(grp.max()),
        })

    if not rows:
        return pd.DataFrame(columns=_EVENT_COLUMNS)
    return pd.DataFrame(rows, columns=_EVENT_COLUMNS).sort_values("start").reset_index(drop=True)


def baseflow_lyne_hollick(q, alpha=0.925, passes=3):
    """Lyne and Hollick recursive digital filter for baseflow separation.

    Parameters
    ----------
    q : pandas.Series
        Streamflow, any consistent unit, indexed by time.
    alpha : float
        Filter parameter. 0.925 is the widely used default from Nathan and
        McMahon (1990) for daily data. Higher values assign more of the
        hydrograph to baseflow.
    passes : int
        Number of forward and backward passes. Three is standard.

    Returns
    -------
    pandas.Series of baseflow, same index.

    Note
    ----
    This filter has no physical basis. It is a signal-processing convention
    that happens to produce hydrologically plausible separations. Different
    alpha values will shift every back-calculated CN in the same direction,
    so report the alpha you used. Sensitivity to alpha is a legitimate
    stretch exercise for the advanced track.

    Source
    ------
    Lyne, V. and Hollick, M. (1979), "Stochastic time-variable rainfall-runoff
    modelling", Institute of Engineers Australia National Conference, 89-93.
    The alpha = 0.925 default and the three-pass convention are from Nathan,
    R.J. and McMahon, T.A. (1990), "Evaluation of automated techniques for
    base flow and recession analyses", Water Resources Research 26(7),
    1465-1473, doi:10.1029/WR026i007p01465. Neither is an NRCS document, and
    baseflow separation appears nowhere in TR-55 or NEH-630 Chapter 10.

    Examples
    --------
    >>> import pandas as pd
    >>> from cnkit import baseflow_lyne_hollick
    >>> q = pd.Series([2., 2., 50., 30., 10., 4., 2., 2.],
    ...               index=pd.date_range("2020-06-01", periods=8))
    >>> [round(float(b), 3) for b in baseflow_lyne_hollick(q)]
    [2.0, 2.0, 2.033, 2.09, 2.123, 2.075, 2.0, 2.0]
    """
    if not isinstance(q, pd.Series):
        raise TypeError("q must be a pandas Series")
    if not np.isfinite(alpha) or not 0.0 <= alpha < 1.0:
        raise ValueError("alpha must be finite and in the interval [0, 1)")
    if isinstance(passes, bool) or not isinstance(passes, (int, np.integer)):
        raise TypeError("passes must be a positive integer")
    if passes < 1:
        raise ValueError("passes must be at least 1")
    if q.empty:
        return pd.Series(dtype=float, index=q.index, name="baseflow")
    values = np.asarray(q.astype(float).ffill().bfill().values)
    if np.any(np.isfinite(values) & (values < 0.0)):
        raise ValueError("q must not contain negative streamflow values")
    if not np.isfinite(values).any():
        return pd.Series(np.nan, index=q.index, name="baseflow")
    total = values.copy()

    for i in range(passes):
        direct = np.zeros_like(total)
        series = total if i % 2 == 0 else total[::-1]
        direct[0] = 0.0
        for t in range(1, len(series)):
            d = (alpha * direct[t - 1]
                 + (1.0 + alpha) / 2.0 * (series[t] - series[t - 1]))
            direct[t] = max(d, 0.0)
        base = np.minimum(series, series - direct)
        total = base if i % 2 == 0 else base[::-1]

    base = np.clip(total, 0.0, values)
    return pd.Series(base, index=q.index, name="baseflow")


def baseflow_local_minimum(q, window_days=5):
    """Local minimum baseflow separation. Simpler, more transparent, defensible.

    Takes the minimum over a centred window, then linearly interpolates
    between the turning points. Easier to explain from a projector than a
    recursive filter, and produces similar answers for basins of this size.

    Source
    ------
    The local minimum method as described in Sloto, R.A. and Crouse, M.Y.
    (1996), "HYSEP: A Computer Program for Streamflow Hydrograph Separation
    and Analysis", USGS Water-Resources Investigations Report 96-4040,
    doi:10.3133/wri964040. Like every separation method it is a convention,
    not a measurement. There is no baseflow separation in TR-55 or NEH-630
    Chapter 10, which is part of why event runoff volumes vary so much
    between studies that all claim to follow NRCS.

    Examples
    --------
    A storm peak on day three, riding on a baseflow that rises from 2 to 4.
    The peak is assigned entirely to direct runoff; the interpolated line
    between the turning points is the baseflow.

    >>> import pandas as pd
    >>> from cnkit import baseflow_local_minimum
    >>> q = pd.Series([2., 3., 60., 30., 10., 5., 4., 4.],
    ...               index=pd.date_range("2020-06-01", periods=8))
    >>> [round(float(b), 3) for b in baseflow_local_minimum(q)]
    [2.0, 2.333, 2.667, 3.0, 3.333, 3.667, 4.0, 4.0]
    """
    if not isinstance(q, pd.Series):
        raise TypeError("q must be a pandas Series")
    if isinstance(window_days, bool) or not isinstance(window_days, (int, np.integer)):
        raise TypeError("window_days must be a positive integer")
    if window_days < 1:
        raise ValueError("window_days must be at least 1")
    if q.empty:
        return pd.Series(dtype=float, index=q.index, name="baseflow")
    s = q.astype(float).ffill().bfill()
    if (s.dropna() < 0.0).any():
        raise ValueError("q must not contain negative streamflow values")
    if not s.notna().any():
        return pd.Series(np.nan, index=q.index, name="baseflow")
    mins = s.rolling(window=window_days, center=True, min_periods=1).min()
    turning = s[s <= mins]
    base = turning.reindex(s.index).interpolate(method="time").ffill().bfill()
    return pd.Series(np.minimum(base.values, s.values),
                     index=s.index, name="baseflow")


def event_runoff_volume(discharge_cfs, drainage_area_sqmi, start, end,
                        recession_days=3, method="local_minimum"):
    """Direct runoff depth in inches for one event.

    Integrates (total flow minus baseflow) from the event start through
    recession_days past the event end, then converts the volume to a depth
    over the drainage area.

    Unit conversion: 1 cfs-day over 1 square mile equals 0.03719 inches.
        (1 ft3/s)(86400 s) / (5280 ft)^2 * 12 in/ft = 0.037190 in

    Source
    ------
    Not a published equation. It is the volume integral that makes the left
    hand side of NEH-630 Chapter 10 Equation 10-1 measurable: Q there is event
    runoff volume expressed as a depth over the drainage area, and this is the
    step that turns a discharge record into that quantity. The unit conversion
    is exact arithmetic. The baseflow separation underneath it is a
    convention; see baseflow_local_minimum.

    Examples
    --------
    >>> import pandas as pd
    >>> from cnkit import event_runoff_volume
    >>> q = pd.Series([2., 2., 50., 30., 10., 4., 2., 2.],
    ...               index=pd.date_range("2020-06-01", periods=8))
    >>> round(float(event_runoff_volume(q, 10.0, "2020-06-02", "2020-06-03")), 4)
    0.3198

    The same hydrograph over twice the drainage area is half the depth, and a
    window with no discharge data returns NaN rather than zero.

    >>> round(float(event_runoff_volume(q, 20.0, "2020-06-02", "2020-06-03")), 4)
    0.1599
    >>> float(event_runoff_volume(q, 10.0, "2021-06-02", "2021-06-03"))
    nan
    """
    if not isinstance(discharge_cfs, pd.Series):
        raise TypeError("discharge_cfs must be a pandas Series")
    if not isinstance(discharge_cfs.index, pd.DatetimeIndex):
        raise TypeError("discharge_cfs must be indexed by a DatetimeIndex")
    if method not in _BASEFLOW_METHODS:
        allowed = ", ".join(sorted(_BASEFLOW_METHODS))
        raise ValueError(f"method must be one of: {allowed}")
    if not np.isfinite(drainage_area_sqmi) or drainage_area_sqmi <= 0.0:
        raise ValueError("drainage_area_sqmi must be finite and greater than zero")
    if not np.isfinite(recession_days) or recession_days < 0.0:
        raise ValueError("recession_days must be finite and non-negative")

    discharge_cfs = discharge_cfs.sort_index()
    if method == "local_minimum":
        base = baseflow_local_minimum(discharge_cfs)
    else:
        base = baseflow_lyne_hollick(discharge_cfs)

    direct = (discharge_cfs.astype(float) - base).clip(lower=0.0)
    window = direct.loc[start:pd.Timestamp(end) + pd.Timedelta(days=recession_days)]

    if len(window) == 0 or not window.notna().any():
        return np.nan

    cfs_days = float(window.sum())
    return cfs_days * CFS_DAY_PER_SQMI_TO_INCHES / float(drainage_area_sqmi)


def build_event_table(precip_hourly, discharge_daily, drainage_area_sqmi,
                      min_dry_hours=6, min_depth_in=1.0, recession_days=3,
                      method="local_minimum"):
    """End to end: hourly precipitation plus daily discharge to a P, Q table.

    This is the single function Module 7 calls. Everything above it is
    plumbing the attendees do not need to see unless they want to.

    Returns
    -------
    pandas.DataFrame with columns start, end, duration_hr, P_in,
    peak_intensity_in_hr, Q_in, runoff_ratio. Rows where Q could not be
    computed, or where Q exceeds P, are dropped and counted in the
    DataFrame's .attrs['dropped'] entry.

    Source
    ------
    Composed of separate_rainfall_events and event_runoff_volume; see those
    for provenance. The 1 inch minimum event depth follows Brandao,
    Schwamback, Ballarin, Ramirez-Avila, Vasconcelos and Oliveira (2025),
    Journal of Hydrology 655, 132941, doi:10.1016/j.jhydrol.2025.132941. The
    Q <= P admissibility filter is required by NEH-630 Chapter 10 Equation
    10-1 itself, which has no solution for Q > P.

    Examples
    --------
    Eight days of synthetic hourly rainfall with one 2 inch storm on the
    second day, against a daily hydrograph over a 10 square mile basin.

    >>> import numpy as np, pandas as pd
    >>> from cnkit import build_event_table
    >>> hours = pd.Timestamp("2020-06-01") + pd.to_timedelta(np.arange(192),
    ...                                                      unit="h")
    >>> p = pd.Series(0.0, index=hours)
    >>> p.iloc[24:28] = 0.5
    >>> q = pd.Series([2., 2., 60., 30., 8., 3., 2., 2.],
    ...               index=pd.date_range("2020-06-01", periods=8))
    >>> ev = build_event_table(p, q, 10.0)
    >>> round(float(ev["P_in"][0]), 2), round(float(ev["Q_in"][0]), 4)
    (2.0, 0.3421)
    >>> ev.attrs["dropped"], ev.attrs["baseflow_method"]
    (0, 'local_minimum')

    A runoff ratio of 0.17 on a 2 inch storm is the ordinary case, and it is
    the regime where the choice of lambda matters most.
    """
    if method not in _BASEFLOW_METHODS:
        allowed = ", ".join(sorted(_BASEFLOW_METHODS))
        raise ValueError(f"method must be one of: {allowed}")

    events = separate_rainfall_events(
        precip_hourly, min_dry_hours=min_dry_hours, min_depth_in=min_depth_in
    )

    q_in = []
    for _, ev in events.iterrows():
        q_in.append(event_runoff_volume(
            discharge_daily, drainage_area_sqmi, ev["start"], ev["end"],
            recession_days=recession_days, method=method,
        ))

    events["Q_in"] = q_in
    n_before = len(events)

    events = events[np.isfinite(events["Q_in"])]
    events = events[(events["Q_in"] > 0) & (events["Q_in"] <= events["P_in"])]
    events["runoff_ratio"] = events["Q_in"] / events["P_in"]

    events = events.reset_index(drop=True)
    events.attrs["dropped"] = n_before - len(events)
    events.attrs["min_depth_in"] = min_depth_in
    events.attrs["min_dry_hours"] = min_dry_hours
    events.attrs["baseflow_method"] = method
    return events


# =========================================================================
# cnkit.asymptotic
# =========================================================================

"""Hawkins asymptotic determination of curve numbers from rainfall-runoff data.

The central empirical fact of this module: a curve number back-calculated from
individual storm events is not constant. It declines systematically with
rainfall depth P. Hawkins (1993) identified three watershed archetypes.

    STANDARD    CN declines monotonically toward a stable asymptote.
                CN(P) = CNinf + (100 - CNinf) * exp(-k*P)
                This is the ONLY behaviour for which the tabulated-CN
                paradigm is defensible, and CNinf is the "correct" CN.

    COMPLACENT  CN declines steadily with no apparent asymptote over the
                observed range. Runoff is a nearly constant small fraction
                of rainfall. NO UNIQUE CN EXISTS. Common in forested and
                deeply permeable watersheds.

    VIOLENT     An abrupt jump to high CN above some rainfall threshold.
                CN(P) = CNinf * (1 - exp(-k*P))
                Suggests saturation-excess or frozen-ground behaviour.

The revised NEH-630 chapters drafted by the EWRI CN Hydrology Task Committee
and submitted to NRCS in September 2017 state that the method is NOT
appropriate for complacent or violent watersheds. Those revisions remain
unimplemented.

References
----------
Hawkins, R.H. (1993). "Asymptotic determination of runoff curve numbers from
    data." J. Irrigation and Drainage Engineering, 119(2), 334-345.
    doi:10.1061/(ASCE)0733-9437(1993)119:2(334)
Hawkins, R.H., Ward, T.J., Woodward, D.E., Van Mullem, J.A., eds. (2009).
    Curve Number Hydrology: State of the Practice. ASCE.
Moglen, G.E., Sadeq, H., Hughes, L.H., Meadows, M.E., Miller, J.J.,
    Ramirez-Avila, J.J., Tollner, E.W. (2022). "NRCS Curve Number Method:
    Comparison of Methods for Estimating the Curve Number from Rainfall-Runoff
    Data." J. Hydrologic Engineering, 27(10).
    doi:10.1061/(ASCE)HE.1943-5584.0002210
    See also the published Discussion (doi:10.1061/JHYEFF.HEENG-5904) and
    Closure (doi:10.1061/JHYEFF.HEENG-6013). The profession does not agree
    on which estimator to use, and the workshop should say so.

EWRI Curve Number Hydrology and Remote Sensing Task Committees, 2026.
"""


def standard_model(P, cn_inf, k):
    """CN(P) = CNinf + (100 - CNinf) * exp(-k*P). Hawkins standard response.

    Source
    ------
    Hawkins, R.H. (1993). "Asymptotic Determination of Runoff Curve Numbers
    from Data." J. Irrigation and Drainage Engineering 119(2), 334-345,
    Equation for the standard response. doi:10.1061/(ASCE)0733-9437(1993)119:2(334)
    This model is not in TR-55 or NEH-630; it is a description of what the
    data does, offered against what the handbook assumes.

    Examples
    --------
    The curve starts at 100 for a vanishing storm and decays to CNinf. That
    the intercept is 100 is not a fitted result, it is built into the form.

    >>> from cnkit import standard_model
    >>> round(float(standard_model(0.0, 75.0, 0.8)), 2)
    100.0
    >>> [round(float(standard_model(p, 75.0, 0.8)), 2) for p in (1.0, 6.0)]
    [86.23, 75.21]
    """
    return cn_inf + (100.0 - cn_inf) * np.exp(-k * np.asarray(P, dtype=float))


def violent_model(P, cn_inf, k):
    """CN(P) = CNinf * (1 - exp(-k*P)). Hawkins violent response.

    Source
    ------
    Hawkins, R.H. (1993). "Asymptotic Determination of Runoff Curve Numbers
    from Data." J. Irrigation and Drainage Engineering 119(2), 334-345.
    doi:10.1061/(ASCE)0733-9437(1993)119:2(334)

    Examples
    --------
    The violent form rises to CNinf from below, the opposite direction to the
    standard form. A watershed doing this is generating runoff by saturation
    excess or over frozen ground, and a tabulated CN does not describe it.

    >>> from cnkit import violent_model
    >>> round(float(violent_model(0.0, 85.0, 0.8)), 2)
    0.0
    >>> [round(float(violent_model(p, 85.0, 0.8)), 2) for p in (1.0, 6.0)]
    [46.81, 84.3]
    """
    return cn_inf * (1.0 - np.exp(-k * np.asarray(P, dtype=float)))


def _validate_model(model):
    if model not in {"standard", "violent"}:
        raise ValueError("model must be 'standard' or 'violent'")
    return model


def _event_arrays(P, Q):
    """Return one-dimensional event arrays with a shared shape."""
    P = np.asarray(P, dtype=float)
    Q = np.asarray(Q, dtype=float)
    if P.ndim != 1 or Q.ndim != 1 or P.shape != Q.shape:
        raise ValueError("P and Q must be one-dimensional arrays of equal length")
    return P, Q


@dataclass
class AsymptoticFit:
    """Result of fitting one Hawkins model to a set of events.

    Attributes are the fitted CNinf, the decay constant k, goodness of fit,
    the number of admissible events, the lambda the fit was done at, whether
    the optimiser converged, and any notes the fitter wanted to leave behind.

    Source
    ------
    Hawkins, R.H. (1993). "Asymptotic Determination of Runoff Curve Numbers
    from Data." J. Irrigation and Drainage Engineering 119(2), 334-345.
    doi:10.1061/(ASCE)0733-9437(1993)119:2(334)
    The `lam` field is carried explicitly because CNinf is only meaningful
    beside the lambda it was fitted at, exactly as a table value is only
    meaningful beside the Ia = 0.2S footnote it was published under.

    Examples
    --------
    >>> from cnkit import AsymptoticFit
    >>> fit = AsymptoticFit(model="standard", cn_inf=75.2, k=0.82, r2=0.98,
    ...                     rmse=0.56, n_events=40, lam=0.20)
    >>> round(float(fit.predict(6.0)), 2)
    75.38
    >>> print(fit)
    standard lambda=0.20 CNinf= 75.20 k=0.8200 r2=0.980 RMSE= 0.56 n=40
    """

    model: str
    cn_inf: float
    k: float
    r2: float
    rmse: float
    n_events: int
    lam: float
    converged: bool = True
    notes: list[str] = field(default_factory=list)

    def predict(self, P):
        """Fitted CN at rainfall depth P, using whichever model was fitted.

        Examples
        --------
        >>> from cnkit import AsymptoticFit
        >>> fit = AsymptoticFit(model="violent", cn_inf=85.0, k=0.8, r2=0.9,
        ...                     rmse=1.0, n_events=40, lam=0.20)
        >>> round(float(fit.predict(6.0)), 2)
        84.3
        """
        _validate_model(self.model)
        f = standard_model if self.model == "standard" else violent_model
        return f(P, self.cn_inf, self.k)

    def __str__(self):
        return (
            f"{self.model:9s} lambda={self.lam:.2f}  "
            f"CNinf={self.cn_inf:6.2f}  k={self.k:.4f}  "
            f"r2={self.r2:5.3f}  RMSE={self.rmse:5.2f}  n={self.n_events}"
        )


def _r2_rmse(observed, predicted):
    observed = np.asarray(observed, dtype=float)
    predicted = np.asarray(predicted, dtype=float)
    resid = observed - predicted
    ss_res = float(np.sum(resid ** 2))
    ss_tot = float(np.sum((observed - observed.mean()) ** 2))
    r2 = 1.0 - ss_res / ss_tot if ss_tot > 0 else np.nan
    rmse = float(np.sqrt(ss_res / len(observed)))
    return r2, rmse


def fit_asymptotic(P, Q, lam=0.20, model="standard", min_events=10):
    """Fit a Hawkins model to paired event rainfall and runoff depths.

    Events are ordered independently by P and by Q before fitting, which is
    the frequency-matching step Hawkins specifies. Pairing the largest P with
    the largest Q (rather than keeping the original storm pairing) removes the
    timing and routing noise that would otherwise dominate the scatter.

    Parameters
    ----------
    P, Q : array-like
        Event rainfall and runoff depths, inches. Same length.
    lam : float
        Initial abstraction ratio. 0.20 or 0.05.
    model : {'standard', 'violent'}
    min_events : int
        Below this the fit is not attempted. Hawkins recommends a minimum of
        roughly 10 to 20 events; fewer than that and CNinf is not identifiable.

    Returns
    -------
    AsymptoticFit

    Source
    ------
    Hawkins, R.H. (1993). "Asymptotic Determination of Runoff Curve Numbers
    from Data." J. Irrigation and Drainage Engineering 119(2), 334-345.
    doi:10.1061/(ASCE)0733-9437(1993)119:2(334)
    Event curve numbers come from NEH-630 Chapter 10 (July 2004) Equations
    10-1 and 10-12, inverted; see cnkit.core.CN_from_PQ. Neither the fit nor
    the frequency matching step appears in any NRCS document.

    Examples
    --------
    A deterministic synthetic watershed that really does behave the way
    Hawkins says a standard watershed behaves: the event curve number decays
    from 100 toward 75 as the storm grows. Five percent multiplicative noise
    is added with a fixed seed so the fit is reproducible.

    >>> import numpy as np
    >>> from cnkit import fit_asymptotic, runoff, standard_model
    >>> rng = np.random.default_rng(0)
    >>> P = np.linspace(0.5, 6.0, 40)
    >>> Q = runoff(P, standard_model(P, 75.0, 0.8)) * rng.uniform(0.95, 1.05, 40)
    >>> fit = fit_asymptotic(P, Q)
    >>> round(fit.cn_inf, 1), round(fit.r2, 2), fit.n_events
    (75.2, 0.98, 40)

    The fit recovers the CNinf of 75 it was built from. Real watersheds are
    rarely this obliging, which is why classify_behaviour exists.
    """
    lam = _validate_lambda(lam)
    model = _validate_model(model)
    if isinstance(min_events, bool) or not isinstance(min_events, (int, np.integer)):
        raise TypeError("min_events must be a positive integer")
    if min_events < 1:
        raise ValueError("min_events must be at least 1")
    P, Q = _event_arrays(P, Q)

    keep = np.isfinite(P) & np.isfinite(Q) & (P > 0) & (Q > 0) & (Q <= P)
    P, Q = P[keep], Q[keep]

    # Frequency matching: sort each independently, then re-pair by rank.
    P = np.sort(P)[::-1]
    Q = np.sort(Q)[::-1]

    cn_event = CN_from_PQ(P, Q, lam=lam)
    ok = np.isfinite(cn_event)
    P, cn_event = P[ok], cn_event[ok]

    notes = []
    if len(P) < min_events:
        return AsymptoticFit(
            model=model, cn_inf=np.nan, k=np.nan, r2=np.nan, rmse=np.nan,
            n_events=len(P), lam=lam, converged=False,
            notes=[f"only {len(P)} admissible events, need {min_events}"],
        )

    f = standard_model if model == "standard" else violent_model
    p0 = [float(np.median(cn_event)), 0.5]
    bounds = ([1.0, 1e-4], [100.0, 20.0])

    try:
        popt, _ = curve_fit(f, P, cn_event, p0=p0, bounds=bounds, maxfev=20000)
        converged = True
    except (RuntimeError, ValueError) as exc:
        notes.append(f"curve_fit failed: {exc}")
        popt, converged = [np.nan, np.nan], False

    if converged:
        r2, rmse = _r2_rmse(cn_event, f(P, *popt))
    else:
        r2 = rmse = np.nan

    return AsymptoticFit(
        model=model, cn_inf=float(popt[0]), k=float(popt[1]),
        r2=r2, rmse=rmse, n_events=len(P), lam=lam,
        converged=converged, notes=notes,
    )


def classify_behaviour(P, Q, lam=0.20, complacent_r2=0.30, plateau_tol=2.0):
    """Classify a watershed as standard, complacent, or violent.

    This is a defensible heuristic, not a definitive test. Hawkins classified
    by eye, and so should you. The workshop should present the plot and let
    the room argue before revealing what this function returns.

    Logic
    -----
    1. Fit both models.
    2. If the violent model fits materially better, call it violent.
    3. Otherwise, if the standard fit has not actually reached an asymptote
       within the observed rainfall range, call it complacent. "Reached" means
       the fitted CN at the largest observed P is within plateau_tol CN units
       of CNinf.
    4. Otherwise standard.

    Returns
    -------
    dict with keys: behaviour, standard, violent, reason

    Source
    ------
    The three-way archetype is Hawkins, R.H. (1993), "Asymptotic
    Determination of Runoff Curve Numbers from Data", J. Irrigation and
    Drainage Engineering 119(2), 334-345,
    doi:10.1061/(ASCE)0733-9437(1993)119:2(334). The thresholds encoded here
    (complacent_r2, plateau_tol, the 0.10 r-squared margin) are this
    package's operationalisation and are NOT in Hawkins, who classified by
    eye. The revised NEH-630 chapters submitted to NRCS in September 2017
    state the asymptotic method is not appropriate for complacent or violent
    watersheds; those revisions remain unimplemented.

    Examples
    --------
    The same synthetic standard watershed used by fit_asymptotic is
    recognised as standard, because the fitted curve flattens inside the
    observed rainfall range.

    >>> import numpy as np
    >>> from cnkit import classify_behaviour, runoff, standard_model
    >>> rng = np.random.default_rng(0)
    >>> P = np.linspace(0.5, 6.0, 40)
    >>> Q = runoff(P, standard_model(P, 75.0, 0.8)) * rng.uniform(0.95, 1.05, 40)
    >>> classify_behaviour(P, Q)["behaviour"]
    'standard'

    A watershed that turns a nearly constant four percent of every storm into
    runoff never reaches an asymptote. There is no single correct curve
    number for it, and the function says so rather than returning one.

    >>> rng = np.random.default_rng(1)
    >>> classify_behaviour(P, 0.04 * P * rng.uniform(0.9, 1.1, 40))["behaviour"]
    'complacent'
    """
    lam = _validate_lambda(lam)
    if not np.isfinite(complacent_r2) or not 0.0 <= complacent_r2 <= 1.0:
        raise ValueError("complacent_r2 must be between 0 and 1")
    if not np.isfinite(plateau_tol) or plateau_tol < 0.0:
        raise ValueError("plateau_tol must be finite and non-negative")

    fit_s = fit_asymptotic(P, Q, lam=lam, model="standard")
    fit_v = fit_asymptotic(P, Q, lam=lam, model="violent")

    if not fit_s.converged and not fit_v.converged:
        return {"behaviour": "indeterminate", "standard": fit_s,
                "violent": fit_v, "reason": "neither model converged"}

    P = np.asarray(P, dtype=float)
    p_max = float(np.nanmax(P[np.isfinite(P)]))

    if fit_v.converged and fit_s.converged and fit_v.r2 > fit_s.r2 + 0.10:
        return {"behaviour": "violent", "standard": fit_s, "violent": fit_v,
                "reason": f"violent r2 {fit_v.r2:.3f} exceeds standard "
                          f"{fit_s.r2:.3f} by more than 0.10"}

    if fit_s.converged:
        cn_at_pmax = float(standard_model(p_max, fit_s.cn_inf, fit_s.k))
        gap = cn_at_pmax - fit_s.cn_inf
        if fit_s.r2 < complacent_r2:
            return {"behaviour": "complacent", "standard": fit_s,
                    "violent": fit_v,
                    "reason": f"standard fit is poor, r2 {fit_s.r2:.3f}, "
                              f"no identifiable asymptote"}
        if gap > plateau_tol:
            return {"behaviour": "complacent", "standard": fit_s,
                    "violent": fit_v,
                    "reason": f"CN at P_max is still {gap:.1f} units above "
                              f"CNinf, asymptote not reached in the data"}
        return {"behaviour": "standard", "standard": fit_s, "violent": fit_v,
                "reason": f"asymptote reached, CN at P_max within "
                          f"{gap:.1f} units of CNinf"}

    return {"behaviour": "violent", "standard": fit_s, "violent": fit_v,
            "reason": "standard model failed to converge"}


# ---------------------------------------------------------------------------
# The other three estimators compared in Moglen et al. (2022).
# They do not agree, and showing that they do not agree is the point.
# ---------------------------------------------------------------------------

def cn_least_squares(P, Q, lam=0.20):
    """CN minimising squared error in runoff depth across all events.

    Source
    ------
    One of the four estimators compared in Moglen, G.E., Sadeq, H., Hughes,
    L.H., Meadows, M.E., Miller, J.J., Ramirez-Avila, J.J., Tollner, E.W.
    (2022), "NRCS Curve Number Method: Comparison of Methods for Estimating
    the Curve Number from Rainfall-Runoff Data", J. Hydrologic Engineering
    27(10), doi:10.1061/(ASCE)HE.1943-5584.0002210. The runoff equation being
    minimised against is NEH-630 Chapter 10 (July 2004) Equation 10-1. NRCS
    does not prescribe an estimator.

    Examples
    --------
    Least squares in runoff DEPTH is dominated by the largest storms, because
    that is where the squared residuals live. On these three events it lands
    ten CN units below the median estimator.

    >>> from cnkit import cn_least_squares
    >>> round(cn_least_squares([1.0, 3.0, 6.0], [0.05, 0.6, 1.6]), 2)
    57.5
    """

    lam = _validate_lambda(lam)
    P, Q = _event_arrays(P, Q)
    keep = np.isfinite(P) & np.isfinite(Q) & (P > 0.0) & (Q >= 0.0) & (Q <= P)
    P, Q = P[keep], Q[keep]
    if P.size == 0:
        raise ValueError("no physically admissible rainfall-runoff pairs")

    def sse(cn):
        return float(np.sum((runoff(P, cn, lam=lam) - Q) ** 2))

    res = minimize_scalar(sse, bounds=(1.0, 99.9), method="bounded")
    return float(res.x)


def cn_median(P, Q, lam=0.20):
    """Median of the event-by-event back-calculated curve numbers.

    Source
    ------
    One of the four estimators compared in Moglen et al. (2022),
    J. Hydrologic Engineering 27(10),
    doi:10.1061/(ASCE)HE.1943-5584.0002210. Event curve numbers come from
    NEH-630 Chapter 10 (July 2004) Equations 10-1 and 10-12, inverted.

    Examples
    --------
    This estimator keeps the storm pairing, so it is sensitive to it. The
    same three storms with the runoff depths re-paired give a completely
    different answer.

    >>> from cnkit import cn_median
    >>> round(cn_median([1.0, 3.0, 6.0], [0.05, 0.6, 1.6]), 2)
    67.36
    >>> round(cn_median([1.0, 3.0, 6.0], [0.6, 1.6, 0.05]), 2)
    85.16
    """
    lam = _validate_lambda(lam)
    P, Q = _event_arrays(P, Q)
    cn = CN_from_PQ(P, Q, lam=lam)
    cn = np.asarray(cn, dtype=float)
    if not np.isfinite(cn).any():
        raise ValueError("no physically admissible rainfall-runoff pairs")
    return float(np.nanmedian(cn))


def cn_ordered(P, Q, lam=0.20):
    """CN from rank-matched (frequency-matched) P and Q, then median.

    This is the estimator implied by the design-storm use case: a 10-year
    rainfall is assumed to produce a 10-year runoff, which is a statement
    about matched exceedance frequencies, not about matched storms.

    Source
    ------
    The frequency matching step is Hawkins, R.H. (1993), J. Irrigation and
    Drainage Engineering 119(2), 334-345,
    doi:10.1061/(ASCE)0733-9437(1993)119:2(334). Included as one of the four
    estimators compared in Moglen et al. (2022), J. Hydrologic Engineering
    27(10), doi:10.1061/(ASCE)HE.1943-5584.0002210.

    Examples
    --------
    Because P and Q are sorted independently before pairing, this estimator
    is invariant to how the storms were matched up in the first place. Both
    calls below return the same number, where cn_median does not.

    >>> from cnkit import cn_ordered
    >>> round(cn_ordered([1.0, 3.0, 6.0], [0.05, 0.6, 1.6]), 2)
    67.36
    >>> round(cn_ordered([1.0, 3.0, 6.0], [0.6, 1.6, 0.05]), 2)
    67.36
    """
    lam = _validate_lambda(lam)
    P, Q = _event_arrays(P, Q)
    keep = np.isfinite(P) & np.isfinite(Q) & (P > 0.0) & (Q > 0.0)
    P = np.sort(P[keep])[::-1]
    Q = np.sort(Q[keep])[::-1]
    if P.size == 0:
        raise ValueError("no positive finite rainfall-runoff pairs")
    cn = CN_from_PQ(P, Q, lam=lam)
    if not np.isfinite(cn).any():
        raise ValueError("no physically admissible rank-matched pairs")
    return float(np.nanmedian(cn))


def compare_estimators(P, Q, lam=0.20):
    """Run all four estimators and return them side by side.

    Expect them to disagree, sometimes by 5 to 10 CN units on the same data.
    Moglen et al. (2022) compared exactly these and drew a published
    Discussion and Closure. Present the spread as a result, not as an error.

    Source
    ------
    Moglen, G.E., Sadeq, H., Hughes, L.H., Meadows, M.E., Miller, J.J.,
    Ramirez-Avila, J.J., Tollner, E.W. (2022). "NRCS Curve Number Method:
    Comparison of Methods for Estimating the Curve Number from
    Rainfall-Runoff Data." J. Hydrologic Engineering 27(10).
    doi:10.1061/(ASCE)HE.1943-5584.0002210
    See also the Discussion (doi:10.1061/JHYEFF.HEENG-5904) and Closure
    (doi:10.1061/JHYEFF.HEENG-6013). NRCS prescribes none of these four.

    Examples
    --------
    Four estimators, one synthetic dataset, four different answers. The
    spread is roughly 1.7 CN units here on data generated from a known
    CNinf of 75; on real records it is routinely 5 to 10.

    >>> import numpy as np
    >>> from cnkit import compare_estimators, runoff, standard_model
    >>> rng = np.random.default_rng(0)
    >>> P = np.linspace(0.5, 6.0, 40)
    >>> Q = runoff(P, standard_model(P, 75.0, 0.8)) * rng.uniform(0.95, 1.05, 40)
    >>> out = compare_estimators(P, Q)
    >>> [round(out[k], 2) for k in ("asymptotic", "least_squares",
    ...                             "median", "ordered")]
    [75.22, 76.29, 76.91, 76.91]
    """
    fit = fit_asymptotic(P, Q, lam=lam, model="standard")
    return {
        "asymptotic": fit.cn_inf,
        "least_squares": cn_least_squares(P, Q, lam=lam),
        "median": cn_median(P, Q, lam=lam),
        "ordered": cn_ordered(P, Q, lam=lam),
        "n_events": fit.n_events,
        "lambda": lam,
    }


# =========================================================================
# cnkit.antecedent
# =========================================================================

"""Antecedent condition: the 1972 rainfall proxy versus the satellite observation.

This module implements both conventions side by side so that the Module 6
exercise can quantify how often they disagree.

THE CLASSIC CONVENTION (and why it was abandoned)
-------------------------------------------------
Antecedent Moisture Condition was keyed to the total rainfall in the five days
preceding the storm, with different thresholds for the dormant and growing
seasons. NRCS itself walked away from this. NEH Part 630 Chapter 10 (2004)
states there is "no apparent relationship between antecedent precipitation and
curve number", and redefines ARC I and ARC III as the 10th and 90th percentiles
of the CN distribution treated as a random variable, not as a moisture state
you can look up from prior rainfall. Twenty-two years later, most practitioners
are still using the 1972 table. It is implemented here so you can show what it
would have said.

THE SATELLITE CONVENTION
------------------------
Replace the class with an observed soil moisture percentile against the pixel's
own day-of-year climatology. Pachon-Acuna, Lopez-Rebollo, Calvo-Montanez,
Del Pozo and Gonzalez-Aguilera (2026), Remote Sensing 18(4), 616,
doi:10.3390/rs18040616, use five bins rather than three and report the number
that makes the whole argument: the Pearson correlation between daily
precipitation and observed soil moisture is only 0.267 to 0.286.

That is the quantitative case that antecedent RAINFALL is a poor proxy for
antecedent WETNESS, which is what NEH-630 concluded qualitatively in 2004
without the data to prove it.

THE HONEST LIMIT
----------------
Satellite radiometers observe 0 to 5 cm and C-band SAR observes 0 to 2 cm,
while S represents an integrated profile deficit that may be a metre deep.
Root-zone products such as SMAP L4 are model-assimilated, not observed.
Mapping observed soil moisture to S is a calibration exercise, not a physical
identity. The percentile approach below is a pragmatic workaround for exactly
this, and should be presented as one.

EWRI Curve Number Hydrology and Remote Sensing Task Committees, 2026.
"""


# The 1972 five-day antecedent rainfall thresholds, inches.
# (upper bound of AMC I, upper bound of AMC II)
AMC_THRESHOLDS_IN = {
    "dormant": (0.5, 1.1),
    "growing": (1.4, 2.1),
}
"""Five-day antecedent rainfall thresholds separating AMC I, II and III.

Source
------
NRCS (1972). National Engineering Handbook Section 4, Hydrology, Chapter 4,
Table 4.2. These thresholds were dropped from the 2004 rewrite: NEH-630
Chapter 10 (July 2004) states there is "no apparent relationship between
antecedent precipitation and curve number" and redefines ARC I and ARC III as
the 10th and 90th percentiles of the curve number distribution. Reproduced
here so the comparison in compare_conventions can be made, not because the
table is current guidance.
"""

# Five soil moisture percentile bins, after Pachon-Acuna et al. (2026).
SM_BINS = [
    (0.0, 20.0, "very dry"),
    (20.0, 40.0, "dry"),
    (40.0, 60.0, "normal"),
    (60.0, 80.0, "wet"),
    (80.0, 100.1, "very wet"),
]
"""Five soil moisture percentile bins, as (low, high, label) triples.

Source
------
Pachon-Acuna, Lopez-Rebollo, Calvo-Montanez, Del Pozo and Gonzalez-Aguilera
(2026). Remote Sensing 18(4), 616. doi:10.3390/rs18040616
Five bins rather than the three ARC classes. The same paper reports the
Pearson correlation between daily precipitation and observed soil moisture as
0.267 to 0.286, which is the quantitative case against the rainfall proxy.
"""

_COMPARISON_COLUMNS = [
    "date",
    "season",
    "P5_in",
    "AMC_class",
    "AMC_direction",
    "SM_percentile",
    "SM_bin",
    "SM_direction",
    "CN_from_AMC",
    "CN_from_SM",
    "CN_difference",
    "conventions_agree",
]


def _datetime_series(values, name):
    if not isinstance(values, pd.Series):
        raise TypeError(f"{name} must be a pandas Series")
    if not isinstance(values.index, pd.DatetimeIndex):
        raise TypeError(f"{name} must be indexed by a DatetimeIndex")
    if values.index.has_duplicates:
        raise ValueError(f"{name} index must not contain duplicate timestamps")
    return values.sort_index().astype(float)


def amc_class_from_rainfall(precip_daily, date, season=None, window_days=5):
    """AMC class I, II, or III from the five-day antecedent rainfall total.

    Parameters
    ----------
    precip_daily : pandas.Series
        Daily precipitation, inches, DatetimeIndex.
    date : str or Timestamp
        The storm date. The window is the five days BEFORE this date,
        exclusive of the storm day itself.
    season : {'dormant', 'growing'} or None
        If None, inferred from the month: April through October is treated
        as growing season for the mid-Atlantic. Override for other regions.

    Returns
    -------
    dict with keys: amc (1, 2, or 3), p5_in, season, thresholds

    Source
    ------
    NRCS (1972). National Engineering Handbook Section 4, Hydrology,
    Chapter 4, Table 4.2. Withdrawn by NEH-630 Chapter 10 (July 2004), which
    states there is "no apparent relationship between antecedent
    precipitation and curve number". Implemented so the workshop can show
    what the 1972 table would have said, not as current guidance.

    Examples
    --------
    Five days at 0.3 inches a day is 1.5 inches of antecedent rainfall. In
    the growing season that is AMC II, an average watershed.

    >>> import pandas as pd
    >>> from cnkit import amc_class_from_rainfall
    >>> p = pd.Series(0.3, index=pd.date_range("2020-07-01", periods=10))
    >>> r = amc_class_from_rainfall(p, "2020-07-08")
    >>> r["amc"], round(r["p5_in"], 2), r["season"]
    (2, 1.5, 'growing')

    The identical 1.5 inches, called dormant season, jumps two classes to
    AMC III. Nothing about the soil changed; only the calendar did.

    >>> amc_class_from_rainfall(p, "2020-07-08", season="dormant")["amc"]
    3
    """
    date = pd.Timestamp(date)
    if season is None:
        season = "growing" if 4 <= date.month <= 10 else "dormant"
    if season not in AMC_THRESHOLDS_IN:
        raise ValueError("season must be 'dormant' or 'growing'")
    if isinstance(window_days, bool) or not isinstance(window_days, (int, np.integer)):
        raise TypeError("window_days must be a positive integer")
    if window_days < 1:
        raise ValueError("window_days must be at least 1")

    precip_daily = _datetime_series(precip_daily, "precip_daily")
    if (precip_daily.dropna() < 0.0).any():
        raise ValueError("precip_daily must not contain negative depths")

    start = date - pd.Timedelta(days=window_days)
    end = date - pd.Timedelta(days=1)
    antecedent = precip_daily.loc[start:end]
    if len(antecedent) != window_days or antecedent.isna().any():
        raise ValueError(
            f"precip_daily must contain all {window_days} antecedent daily values"
        )
    p5 = float(antecedent.sum())

    lo, hi = AMC_THRESHOLDS_IN[season]
    amc = 1 if p5 < lo else (2 if p5 <= hi else 3)

    return {"amc": amc, "p5_in": p5, "season": season,
            "thresholds": (lo, hi), "window_days": window_days}


def doy_climatology(sm, window=15, min_years=3):
    """Day-of-year climatology of a soil moisture series.

    A plain day-of-year grouping is too noisy with only ten years of SMAP, so
    each day-of-year pools all observations within +/- `window` days across all
    years. That is what makes a percentile meaningful with a short record.

    Parameters
    ----------
    sm : pandas.Series
        Soil moisture, any consistent unit, DatetimeIndex.
    window : int
        Half-width of the day-of-year pooling window, in days.
    min_years : int
        A day-of-year with fewer than this many distinct years contributing
        is returned as NaN rather than as a falsely precise climatology.

    Returns
    -------
    dict mapping day-of-year (1 to 366) to a numpy array of pooled values.

    Source
    ------
    No published source. A moving day-of-year window is standard practice for
    building a climatology from a short satellite record; the window half
    width and the minimum-years rule here are this package's choices. State
    them whenever you report a percentile derived from this.

    Examples
    --------
    Six years of daily values, pooled over plus or minus 15 days. Every
    day-of-year draws on 31 days times 6 years, which is 186 observations.

    >>> import numpy as np, pandas as pd
    >>> from cnkit import doy_climatology
    >>> idx = pd.date_range("2015-01-01", "2020-12-31")
    >>> sm = pd.Series(0.25 + 0.05 * np.sin(2 * np.pi * idx.dayofyear / 365.25),
    ...                index=idx)
    >>> clim = doy_climatology(sm)
    >>> len(clim), int(clim[100].size)
    (366, 186)
    """
    if isinstance(window, bool) or not isinstance(window, (int, np.integer)):
        raise TypeError("window must be a non-negative integer")
    if not 0 <= window <= 183:
        raise ValueError("window must be between 0 and 183 days")
    if isinstance(min_years, bool) or not isinstance(min_years, (int, np.integer)):
        raise TypeError("min_years must be a positive integer")
    if min_years < 1:
        raise ValueError("min_years must be at least 1")
    s = _datetime_series(sm, "sm").dropna()
    doy = s.index.dayofyear.values
    years = s.index.year.values
    values = s.values

    clim = {}
    for d in range(1, 367):
        # Circular distance in day-of-year space.
        diff = np.abs(doy - d)
        diff = np.minimum(diff, 366 - diff)
        sel = diff <= window
        if sel.sum() == 0 or len(np.unique(years[sel])) < min_years:
            clim[d] = np.array([])
        else:
            clim[d] = values[sel]
    return clim


def sm_percentile(sm, date, climatology=None, window=15):
    """Percentile of the soil moisture on `date` against its DOY climatology.

    Returns NaN if the date is missing from the series or the climatology for
    that day-of-year is too thin to support a percentile.

    Source
    ------
    The percentile-against-own-climatology framing follows Pachon-Acuna,
    Lopez-Rebollo, Calvo-Montanez, Del Pozo and Gonzalez-Aguilera (2026),
    Remote Sensing 18(4), 616, doi:10.3390/rs18040616. The three-day nearest
    observation tolerance is a practical allowance for SMAP revisit gaps and
    is not from any source.

    Examples
    --------
    The percentile is against the pixel's own day-of-year climatology, not
    against the whole record, so a seasonal cycle does not by itself make a
    day look wet or dry.

    >>> import numpy as np, pandas as pd
    >>> from cnkit import sm_percentile
    >>> idx = pd.date_range("2015-01-01", "2020-12-31")
    >>> sm = pd.Series(0.25 + 0.05 * np.sin(2 * np.pi * idx.dayofyear / 365.25),
    ...                index=idx)
    >>> round(sm_percentile(sm, "2018-04-10"), 1)
    48.4
    """
    date = pd.Timestamp(date)
    sm = _datetime_series(sm, "sm")
    if climatology is None:
        climatology = doy_climatology(sm, window=window)

    s = sm.dropna().astype(float)
    # Nearest available observation within 3 days, since SMAP has gaps.
    idx = s.index
    deltas = np.abs((idx - date).total_seconds())
    if len(deltas) == 0:
        return np.nan
    j = int(np.argmin(deltas))
    if deltas[j] > 3 * 86400:
        return np.nan
    value = float(s.iloc[j])

    pool = climatology.get(int(date.dayofyear), np.array([]))
    if pool.size < 10:
        return np.nan

    return float((pool < value).sum() / pool.size * 100.0)


def sm_class_from_percentile(pct):
    """Map a percentile to one of the five bins. Returns None for NaN.

    Source
    ------
    Bin edges from Pachon-Acuna, Lopez-Rebollo, Calvo-Montanez, Del Pozo and
    Gonzalez-Aguilera (2026), Remote Sensing 18(4), 616,
    doi:10.3390/rs18040616. Five bins, against the three ARC classes of
    NEH-630 Chapter 10.

    Examples
    --------
    >>> from cnkit import sm_class_from_percentile
    >>> [sm_class_from_percentile(p) for p in (15.0, 55.0, 95.0)]
    ['very dry', 'normal', 'very wet']

    A missing observation returns None rather than quietly falling into the
    middle bin. Absence of data is not evidence of normal wetness.

    >>> sm_class_from_percentile(float("nan")) is None
    True
    """
    if pct is None or not np.isfinite(pct):
        return None
    pct = float(np.clip(pct, 0.0, 100.0))
    for lo, hi, label in SM_BINS:
        if lo <= pct < hi:
            return label
    return "very wet"


def cn_for_amc_class(cn2, amc):
    """CN adjusted to the given AMC class. amc is 1, 2, or 3.

    Source
    ------
    Delegates to cnkit.core.arc1_from_arc2 and arc3_from_arc2, which are
    least squares fits to NEH-630 Chapter 10 Table 10-1 published by Hawkins,
    Hjelmfelt and Zevenbergen (1985), J. Irrigation and Drainage Engineering
    111(4), 330-340, doi:10.1061/(ASCE)0733-9437(1985)111:4(330). They are
    NOT NRCS equations; NEH-630 Chapter 10 has the table and no conversion
    formulae.

    Examples
    --------
    >>> from cnkit import cn_for_amc_class
    >>> [round(cn_for_amc_class(70, a), 2) for a in (1, 2, 3)]
    [49.49, 70.0, 84.29]

    Thirty-five curve numbers separate the dry class from the wet one on the
    same watershed, chosen by a five-day rainfall total.
    """
    if amc == 1:
        return float(arc1_from_arc2(cn2))
    if amc == 3:
        return float(arc3_from_arc2(cn2))
    if amc == 2:
        return float(cn2)
    raise ValueError("amc must be 1, 2, or 3")


def cn_for_sm_percentile(cn2, pct):
    """CN adjusted by interpolating between CN1, CN2 and CN3 on percentile.

    The three ARC curve numbers are anchored at the 10th, 50th and 90th
    percentiles, which is how NEH-630 Chapter 10 (2004) actually defines
    ARC I and ARC III: the 10th and 90th percentiles of the CN distribution
    treated as a random variable.

    Interpolating between them, rather than snapping to three discrete
    classes, is the natural continuous generalisation and is what makes a
    satellite percentile usable directly. Values are clamped outside the
    10th to 90th percentile range because the anchors are not defined there.

    This is a defensible convention, not a published standard. Say so.

    Source
    ------
    The 10th, 50th and 90th percentile anchoring is NEH-630 Chapter 10
    (July 2004), which defines ARC I and ARC III as the 10th and 90th
    percentiles of the curve number distribution. The CN1 and CN3 values
    themselves come from the 1985 Hawkins, Hjelmfelt and Zevenbergen fits,
    doi:10.1061/(ASCE)0733-9437(1985)111:4(330), not from NRCS. The linear
    interpolation between the three anchors, and the clamping outside the
    10th to 90th range, are this package's convention and are not published
    anywhere.

    Examples
    --------
    At the 10th, 50th and 90th percentiles the function reproduces CN1, CN2
    and CN3 exactly, and in between it is continuous rather than stepped.

    >>> from cnkit import cn_for_sm_percentile
    >>> [round(cn_for_sm_percentile(70, p), 2) for p in (10.0, 50.0, 90.0)]
    [49.49, 70.0, 84.29]
    >>> round(cn_for_sm_percentile(70, 75.0), 2)
    78.93

    A missing percentile falls back to the unadjusted CN2 rather than
    guessing a wetness state.

    >>> round(cn_for_sm_percentile(70, float("nan")), 2)
    70.0
    """
    if pct is None or not np.isfinite(pct):
        return float(cn2)

    cn1 = float(arc1_from_arc2(cn2))
    cn3 = float(arc3_from_arc2(cn2))
    p = float(np.clip(pct, 10.0, 90.0))

    if p <= 50.0:
        f = (p - 10.0) / 40.0
        return cn1 + f * (float(cn2) - cn1)
    f = (p - 50.0) / 40.0
    return float(cn2) + f * (cn3 - float(cn2))


def compare_conventions(storm_dates, precip_daily, sm, cn2,
                        design_depth_in=None, window=15):
    """Both conventions, side by side, for a list of storm dates.

    This is the Module 6 exercise in one call. Feed it five storms and look
    at the disagreement column.

    Returns
    -------
    pandas.DataFrame, one row per storm, with the AMC class, the soil
    moisture percentile, the CN each convention implies, and (if a design
    depth is supplied) the runoff depth each implies.

    Source
    ------
    The rainfall convention is NEH-4 (1972) Chapter 4 Table 4.2, withdrawn by
    NEH-630 Chapter 10 (July 2004). The percentile convention follows
    Pachon-Acuna, Lopez-Rebollo, Calvo-Montanez, Del Pozo and
    Gonzalez-Aguilera (2026), Remote Sensing 18(4), 616,
    doi:10.3390/rs18040616. Runoff depths come from NEH-630 Chapter 10
    Equation 10-1.

    Examples
    --------
    One dormant-season storm. The five-day rainfall total is 1.5 inches, so
    the 1972 table calls the watershed WET and hands over CN 84.3. The
    observed soil moisture on that day sits at the bottom of its day-of-year
    climatology, so the satellite calls it DRY and hands over CN 49.5.

    >>> import numpy as np, pandas as pd
    >>> from cnkit import compare_conventions
    >>> idx = pd.date_range("2015-01-01", "2020-12-31")
    >>> sm = pd.Series(0.25 + 0.05 * np.sin(2 * np.pi * idx.dayofyear / 365.25),
    ...                index=idx)
    >>> sm.loc["2018-01-20"] = 0.05
    >>> out = compare_conventions(["2018-01-20"], pd.Series(0.3, index=idx),
    ...                           sm, 70)
    >>> row = out.loc[0]
    >>> row["AMC_direction"], row["SM_direction"]
    ('wet', 'dry')
    >>> float(row["CN_from_AMC"]), float(row["CN_from_SM"])
    (84.3, 49.5)
    >>> out.attrs["disagreement_rate"]
    1.0

    Thirty-five curve numbers apart, pointing in opposite directions, on the
    same day. That gap is the module's whole argument.
    """

    clim = doy_climatology(sm, window=window)
    rows = []

    for d in storm_dates:
        d = pd.Timestamp(d)
        amc = amc_class_from_rainfall(precip_daily, d)
        pct = sm_percentile(sm, d, climatology=clim)
        sm_label = sm_class_from_percentile(pct)

        cn_amc = cn_for_amc_class(cn2, amc["amc"])
        cn_sm = cn_for_sm_percentile(cn2, pct)

        # Do the two conventions point the same direction relative to average?
        amc_dir = {1: "dry", 2: "normal", 3: "wet"}[amc["amc"]]
        sm_dir = ("dry" if (pct is not None and np.isfinite(pct) and pct < 40)
                  else "wet" if (pct is not None and np.isfinite(pct) and pct > 60)
                  else "normal" if pct is not None and np.isfinite(pct) else None)

        row = {
            "date": d,
            "season": amc["season"],
            "P5_in": round(amc["p5_in"], 2),
            "AMC_class": amc["amc"],
            "AMC_direction": amc_dir,
            "SM_percentile": None if pct is None or not np.isfinite(pct) else round(pct, 1),
            "SM_bin": sm_label,
            "SM_direction": sm_dir,
            "CN_from_AMC": round(cn_amc, 1),
            "CN_from_SM": round(cn_sm, 1),
            "CN_difference": round(cn_sm - cn_amc, 1),
            "conventions_agree": (sm_dir is not None and amc_dir == sm_dir),
        }

        if design_depth_in is not None:
            q_amc = float(runoff(design_depth_in, cn_amc))
            q_sm = float(runoff(design_depth_in, cn_sm))
            row["Q_from_AMC_in"] = round(q_amc, 3)
            row["Q_from_SM_in"] = round(q_sm, 3)
            row["Q_ratio"] = round(q_sm / q_amc, 2) if q_amc > 0 else np.nan

        rows.append(row)

    columns = list(_COMPARISON_COLUMNS)
    if design_depth_in is not None:
        columns += ["Q_from_AMC_in", "Q_from_SM_in", "Q_ratio"]
    out = pd.DataFrame(rows, columns=columns)
    n_valid = int(out["SM_direction"].notna().sum())
    n_agree = int(out["conventions_agree"].sum())
    out.attrs["n_comparable"] = n_valid
    out.attrs["n_agree"] = n_agree
    out.attrs["disagreement_rate"] = (
        None if n_valid == 0 else round(1.0 - n_agree / n_valid, 3)
    )
    return out
